// Parent class — the shared blueprint
class Animal {
    protected String name;             // field available to subclasses

    Animal(String name) {
        this.name = name;              // constructor sets the name
    }

    void eat() {
        System.out.println(name + " is eating");  // shared behaviour
    }

    String sound() {
        return "...";                  // default; subclasses will override
    }
}

// Child class — inherits everything above, then adds its own
class Dog extends Animal {             // Dog IS-A Animal ✓

    Dog(String name) {
        super(name);                   // call parent constructor first
    }

    @Override                          // tells compiler: intentional override
    String sound() {
        return "Woof";                 // specialised version of sound()
    }

    void fetch() {
        System.out.println(name + " fetches the ball!");  // Dog-only method
    }
}

// Usage
public class Main {
    public static void main(String[] args) {
        Dog rex = new Dog("Rex");
        rex.eat();                     // inherited from Animal → Rex is eating
        System.out.println(rex.sound()); // overridden → Woof
        rex.fetch();                   // Dog-only → Rex fetches the ball!

        Animal a = rex;                // polymorphism: Dog treated as Animal
        System.out.println(a.sound()); // still Woof — runtime dispatch
    }
}
```

